import { afterAll, beforeAll, describe, it, expect, vi } from "vitest";
import { randomUUID } from "node:crypto";
import { Client } from "pg";
import { PrismaClient } from "@/generated/prisma/client";
import { PrismaPg } from "@prisma/adapter-pg";
import {
  createIsolatedDatabase,
  databaseTestsEnabled,
} from "./helpers/foundation-db";
import { provisionAdminRole } from "../scripts/provision-admin-db";
const state = vi.hoisted(() => ({
  db: null as unknown as PrismaClient,
  session: {} as unknown,
}));
vi.mock("@/auth", () => ({ auth: async () => state.session }));
vi.mock("@/lib/admin/db", () => ({ adminDb: () => state.db }));
vi.mock("@/lib/db", () => ({ db: {} }));
import { getAdminUser, listUsers, listAudit } from "@/lib/admin/queries";
import { changeOverride, changeSuspension } from "@/lib/admin/mutations";
describe.runIf(databaseTestsEnabled)(
  "operator response privacy under failures",
  () => {
    let f: Awaited<ReturnType<typeof createIsolatedDatabase>>, role: string;
    const actor = randomUUID(),
      target = randomUUID(),
      secrets = [
        "refresh",
        "subject",
        "body",
        "contact",
        "path",
        "webhook",
        "reason",
      ].map((x) => `${x}-SENTINEL-${randomUUID()}`);
    beforeAll(async () => {
      f = await createIsolatedDatabase();
      for (const m of f.migrations) await f.apply(m);
      role = "privacy_" + randomUUID().replaceAll("-", "");
      const url = new URL(f.url);
      url.username = role;
      url.password = randomUUID() + randomUUID();
      await provisionAdminRole(f.client, url.toString(), f.schema);
      state.db = new PrismaClient({
        adapter: new PrismaPg(
          { connectionString: url.toString() },
          { schema: f.schema },
        ),
        log: [],
      });
      await f.client.query(
        `INSERT INTO "User" (id,email,"isAdmin","googleId","encryptedRefreshToken") VALUES ($1,$2,true,$3,$4)`,
        [actor, `${actor}@example.test`, secrets[1], secrets[0]],
      );
      await f.client.query(
        `INSERT INTO "User" (id,email,"googleId","encryptedRefreshToken","planOverride","planOverrideStartsAt","planOverrideReason") VALUES ($1,$2,$3,$4,'PAID',now(),$5)`,
        [
          target,
          `${target}@example.test`,
          secrets[1] + "target",
          secrets[0],
          secrets[6],
        ],
      );
      await f.client.query(
        `INSERT INTO "Template" (id,"userId",name,subject,body) VALUES ($1,$2,$3,$3,$3)`,
        [randomUUID(), target, secrets[2]],
      );
      await f.client.query(
        `INSERT INTO "Contact" (id,"userId",name,email,notes) VALUES ($1,$2,$3,$4,$3)`,
        [randomUUID(), target, secrets[3], `${target}@private.test`],
      );
      await f.client.query(
        `INSERT INTO "Attachment" (id,"userId","fileName","storagePath") VALUES ($1,$2,'resume.pdf',$3)`,
        [randomUUID(), target, secrets[4]],
      );
      await f.client.query(
        `INSERT INTO "BillingWebhookEvent" (id,"webhookId","eventType","businessId","occurredAt","normalizedData","payloadHash") VALUES ($1,$1,'test','test',now(),$2,$3)`,
        [randomUUID(), JSON.stringify({ secret: secrets[5] }), "b".repeat(64)],
      );
    }, 30000);
    afterAll(async () => {
      await state.db?.$disconnect();
      await f?.cleanup();
      if (role) {
        const c = new Client({ connectionString: process.env.DATABASE_URL });
        await c.connect();
        await c.query(`DROP OWNED BY "${role}"`);
        await c.query(`DROP ROLE "${role}"`);
        await c.end();
      }
    });
    it("recursively checks success, validation, denial, conflict, replay, and injected database failure responses and logs", async () => {
      const logs: unknown[] = [];
      const spies = ["error", "warn", "info", "log"].map((method) =>
        vi
          .spyOn(console, method as "error")
          .mockImplementation((...args: unknown[]) => {
            logs.push(args);
          }),
      );
      const results: unknown[] = [];
      try {
        state.session = {
          user: { id: actor },
          adminAuthAt: Math.floor(Date.now() / 1000),
          adminAuthUserId: actor,
        };
        results.push(
          await getAdminUser(target),
          await listUsers({}),
          await listAudit({}),
        );
        const input = {
          targetId: target,
          plan: null,
          startsAt: null,
          expiresAt: null,
          reasonCode: "SUPPORT",
          requestId: randomUUID(),
          confirmation: false,
        };
        results.push(
          await changeOverride(input),
          await changeOverride(input),
          await changeOverride({ ...input, confirmation: true }),
          await changeOverride({ ...input, reasonCode: secrets[6] }),
        );
        results.push(
          await changeSuspension({
            targetId: actor,
            suspended: true,
            reasonCode: "SECURITY",
            requestId: randomUUID(),
          }),
        );
        await f.client.query(
          `CREATE FUNCTION private_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION '${secrets[0]}'; END $$; CREATE TRIGGER private_failure BEFORE INSERT ON "AdminAuditLog" FOR EACH ROW EXECUTE FUNCTION private_failure()`,
        );
        try {
          results.push(
            await changeSuspension({
              targetId: target,
              suspended: true,
              reasonCode: "SECURITY",
              requestId: randomUUID(),
            }),
          );
        } finally {
          await f.client.query(
            'DROP TRIGGER private_failure ON "AdminAuditLog"; DROP FUNCTION private_failure()',
          );
        }
        state.session = null;
        results.push(await changeOverride(input));
        const serialized = JSON.stringify({ results, logs });
        for (const secret of secrets) expect(serialized).not.toContain(secret);
        expect(results).toContainEqual({ ok: false, code: "UNAVAILABLE" });
        expect(results).toContainEqual({ ok: false, code: "DENIED" });
        expect(results).toContainEqual({ ok: false, code: "CONFLICT" });
      } finally {
        spies.forEach((s) => s.mockRestore());
      }
    });
  },
);
